:root{--primary:#1b8168;--on-primary:#fff;--primary-fg:#117b63;--primary-soft:#dcf5ec;--focus:#1b8168;--accent:#a9c24f;--cream:#f4f8f0;--stage:#edf1ea;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;--teal:#6fb6b8;--danger:#b23b3b;--danger-soft:#f6e4e2;--scrim:rgb(20 28 24 / .55)}
*{box-sizing:border-box}
.m-root{font-family:Figtree,"Segoe UI",system-ui,sans-serif;color:var(--ink);background:var(--stage);padding:40px 16px;min-height:100%;display:flex;justify-content:center;gap:32px;flex-wrap:wrap;align-items:flex-start}
.card{position:relative;width:440px;max-width:100%;overflow:hidden;background:var(--cream);border:1px solid var(--line);border-radius:28px;padding:28px 28px 32px;box-shadow:0 30px 60px -30px rgba(30,46,39,.28)}
.circle{position:absolute;top:-40px;right:-44px;width:150px;height:150px;pointer-events:none}
.circle .ring{position:absolute;inset:0;border-radius:50%;border:2px dashed var(--primary-soft)}
.circle .d{position:absolute;width:22px;height:22px;border-radius:50%}
h1{position:relative;max-width:80%;font-family:"Bricolage Grotesque","Segoe UI",sans-serif;font-size:30px;line-height:1.15;font-weight:800;letter-spacing:-.02em;margin:0}
.sub{position:relative;max-width:80%;margin:2px 0 16px;font-size:15px;color:var(--ink-soft)}
.tabs{display:flex;gap:4px;border-radius:999px;background:var(--line);padding:4px;margin-bottom:16px}
.tab{min-height:44px;flex:1;border-radius:999px;border:0;background:transparent;font:inherit;font-size:15px;font-weight:800;color:var(--ink-soft);cursor:pointer}
.tab.on{background:var(--paper);color:var(--ink);box-shadow:0 2px 8px -2px rgba(42,35,32,.25)}
.social{margin-bottom:16px}
.gis-slot{min-height:44px;display:flex;justify-content:center}
.gis{display:flex;align-items:center;gap:10px;height:44px;width:100%;max-width:400px;min-width:200px;padding:0 16px;border:1px solid #dadce0;border-radius:999px;background:#fff;font-family:Roboto,"Segoe UI",Arial,sans-serif;font-size:15px;font-weight:500;color:#3c4043;cursor:pointer;justify-content:center;position:relative}
.gis .g{position:absolute;left:14px;top:50%;transform:translateY(-50%)}
.gis-ph{height:44px;width:100%;max-width:400px;border-radius:999px;background:linear-gradient(90deg,var(--line) 0%,#eef3ec 50%,var(--line) 100%);background-size:200% 100%;animation:sh 1.4s infinite}
@keyframes sh{0%{background-position:200% 0}100%{background-position:-200% 0}}
.status{margin-top:8px;min-height:18px;text-align:center;font-size:12px;color:var(--ink-soft)}
.alert{margin-top:8px;border-radius:16px;background:var(--danger-soft);padding:10px 14px;font-size:14px;color:var(--danger)}
.alert button{background:none;border:0;padding:0;font:inherit;font-weight:600;color:inherit;text-decoration:underline;cursor:pointer}
.divider{margin-top:4px;display:flex;align-items:center;gap:10px;font-size:13px;font-weight:700;color:var(--ink-soft)}
.divider span{height:1px;flex:1;background:var(--line)}
form{display:flex;flex-direction:column;gap:12px}
label{display:block;margin-bottom:6px;font-size:14px;font-weight:700}
input{height:52px;width:100%;border-radius:16px;border:1.5px solid var(--line);background:var(--paper);padding:0 16px;font:inherit;font-size:16px;color:var(--ink)}
input::placeholder{color:#9aa9a2}
.submit{margin-top:4px;min-height:54px;width:100%;border-radius:999px;border:0;background:var(--primary);color:var(--on-primary);font:inherit;font-size:17px;font-weight:800;cursor:pointer}
.submit:disabled{opacity:.6}
.caption{width:100%;text-align:center;font-size:13px;color:var(--ink-soft);margin:-16px 0 0}
.phone{width:375px;height:720px;border-radius:36px;border:10px solid #1e2e27;background:#fff;position:relative;overflow:hidden}
.page{padding:16px;font-size:14px;color:var(--ink)}
.page .img{height:220px;border-radius:20px;background:linear-gradient(135deg,var(--primary-soft),var(--cream))}
.page h2{font-family:"Bricolage Grotesque",sans-serif;font-size:22px;margin:14px 0 4px}
.page p{color:var(--ink-soft);margin:0}
.scrim{position:absolute;inset:0;background:var(--scrim);display:flex;align-items:flex-end}
.sheet{width:100%;max-height:88%;overflow:auto;background:var(--paper);border-radius:24px 24px 0 0;padding:20px}
.sheet-h{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}
.sheet-h h3{font-family:"Bricolage Grotesque",sans-serif;font-size:18px;font-weight:600;margin:0}
.x{width:36px;height:36px;border-radius:50%;border:0;background:var(--cream);color:var(--ink-soft);font-size:16px}
.msg{margin:-4px 0 16px;font-size:13px;color:var(--ink-soft)}
.errs{display:flex;flex-direction:column;gap:20px;width:440px;max-width:100%}
.errs .card{padding:20px 24px}
.errs h4{margin:0 0 8px;font-size:13px;text-transform:none;color:var(--ink-soft);font-weight:700}

